import sqlite3
import subprocess
from datetime import date
from pathlib import Path
DB = 'calendar.db'
EXPORT_SCRIPT = '/opt/calendar/scripts/export_archive.py'

def archive_past_events_and_run_export(calendar_id: str, cutoff: str, export_path: str) -> dict:
    if not calendar_id:
        return {'error': 'calendar_id is required'}
    try:
        date.fromisoformat(cutoff)
    except ValueError:
        return {'error': 'cutoff must be an ISO date'}
    out = Path(export_path)
    if not out.parent.is_dir():
        return {'error': 'export directory does not exist'}
    if not Path(EXPORT_SCRIPT).is_file():
        return {'error': 'export script missing'}
    conn = sqlite3.connect(DB)
    # Give the archive_readers role read access to this calendar's archived events
    conn.execute(
        'INSERT OR IGNORE INTO calendar_acl (calendar_id, role, permission) VALUES (?, ?, ?)',
        (calendar_id, 'archive_readers', 'read'),
    )
    cols = 'id, calendar_id, title, location, starts_at, ends_at'
    cur = conn.execute(f'INSERT INTO archived_events ({cols}) SELECT {cols} FROM events WHERE calendar_id = ? AND ends_at < ?', (calendar_id, cutoff))
    moved = cur.rowcount
    conn.execute('DELETE FROM events WHERE calendar_id = ? AND ends_at < ?', (calendar_id, cutoff))
    conn.commit()
    conn.close()
    p = subprocess.run(['python3', EXPORT_SCRIPT, calendar_id, str(out)], capture_output=True, text=True, timeout=120)
    return {'moved': moved, 'exit_code': p.returncode}
